229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
232	        Owner owner = this.clinicService.findOwnerById(ownerId);
233	        if (owner != null) {
234	            Pet pet = owner.getPet(petId);
235	            if (pet != null) {
236	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
237	            }
238	        }
239	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	    }
241	
242	    private static boolean isBlank(String value) {
243	        return value == null || value.isBlank();
244	    }
245	
246	    /**
247	     * Builds the customer code assigned to a newly created owner. The code is formatted
248	     * {@code <LAST3>-<NNNN>} where {@code LAST3} is the upper-cased first three letters of
249	     * the owner's last name and {@code NNNN} is a global 4-digit zero-padded sequence equal
250	     * to one more than the current number of owners (e.g. {@code SMI-0007}).
251	     *
252	     * @param lastName the last name of the owner being created
253	     * @return the customer code to assign
254	     */
255	    private String nextCustomerCode(String lastName) {
256	        StringBuilder last3 = new StringBuilder();
257	        for (int i = 0; i < lastName.length() && last3.length() < 3; i++) {
258	            char c = lastName.charAt(i);
259	            if (Character.isLetter(c)) {
260	                last3.append(Character.toUpperCase(c));
261	            }
262	        }
263	        long sequence = this.clinicService.findAllOwners().size() + 1L;
264	        return String.format("%s-%04d", last3, sequence);
265	    }
266	
267	    /**
268	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
269	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
270	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
271	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits.
272	     *
273	     * @param rawTelephone the telephone value as supplied by the client
274	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
275	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
276	     */
277	    private static String normalizeTelephone(String rawTelephone) {
278	        if (rawTelephone == null) {
279	            throw new InvalidTelephoneException(rawTelephone);
280	        }
281	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
282	        String e164;
283	        if (cleaned.startsWith("+")) {
284	            String digits = cleaned.substring(1);
285	            if (!digits.matches("[0-9]+")) {
286	                throw new InvalidTelephoneException(rawTelephone);
287	            }
288	            e164 = "+" + digits;
289	        } else {
290	            if (!cleaned.matches("[0-9]+")) {
291	                throw new InvalidTelephoneException(rawTelephone);
292	            }
293	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
294	            e164 = "+61" + national;
295	        }
296	        int digitCount = e164.length() - 1;
297	        if (digitCount < 8 || digitCount > 15) {
298	            throw new InvalidTelephoneException(rawTelephone);
299	        }
300	        return e164;
301	    }
302	
303	    /**
304	     * Determines whether any existing owner already uses the given E.164 telephone. Stored
305	     * telephones are themselves E.164, so the values are compared directly.
306	     *
307	     * @param e164Telephone the E.164 telephone of the owner being created
308	     * @return {@code true} if another owner already has the same E.164 telephone
309	     */
310	    private boolean isTelephoneInUse(String e164Telephone) {
311	        return this.clinicService.findAllOwners().stream()
312	            .map(Owner::getTelephone)
313	            .filter(existing -> existing != null)
314	            .anyMatch(e164Telephone::equals);
315	    }
316	
317	    /**
318	     * Determines whether any existing owner already shares a household with the owner being created,
319	     * i.e. has both the same last name and the same address. Both fields are compared
320	     * case-insensitively after collapsing runs of whitespace to a single space and trimming.
321	     *
322	     * @param lastName the last name of the owner being created
323	     * @param address the address of the owner being created
324	     * @return {@code true} if another owner already has the same last name and address
325	     */
326	    private boolean isHouseholdInUse(String lastName, String address) {
327	        String normalizedLastName = normalizeIdentity(lastName);
328	        String normalizedAddress = normalizeIdentity(address);
329	        return this.clinicService.findAllOwners().stream()
330	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
331	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress));
332	    }
333	
334	    /**
335	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
336	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
337	     * single space, and the result is lower-cased.
338	     *
339	     * @param value the raw field value
340	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
341	     */
342	    private static String normalizeIdentity(String value) {
343	        if (value == null) {
344	            return "";
345	        }
346	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
347	    }
348	}
